    ? `
if [ "$1" = mcp ]; then
  echo "mcp failed" >&2
  exit 1
460→fi
`
    : "";
  writeFileSync(
    join(bin, "hermes"),
    `#!/bin/sh
echo "$@" >> "${log}"
if [ "$1" = cron ] && [ "$2" = list ]; then
  printf '%s' '${listOut.replace(/'/g, "")}'
fi
470→${failMcp}
exit 0
`,
  );
  chmodSync(join(bin, "hermes"), 0o755);
  return { bin, log };
}

